import{_ as a,o as r,c as t,a4 as o,a6 as i,a7 as n,a8 as s,a9 as l}from"./chunks/framework.BDwB2oh8.js";const g=JSON.parse('{"title":"最重要的功能——搜索","description":"","frontmatter":{"prev":{"text":"主页","link":"/helper/"},"next":{"text":"歌曲详情","link":"/helper/function/songinfo/"}},"headers":[],"relativePath":"helper/function/search/index.md","filePath":"helper/function/search/index.md"}'),p={name:"helper/function/search/index.md"};function c(d,e,h,m,b,_){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="最重要的功能——搜索" tabindex="-1">最重要的功能——搜索 <a class="header-anchor" href="#最重要的功能——搜索" aria-label="Permalink to “最重要的功能——搜索”">​</a></h1><p><img src="'+i+'" alt="搜索界面"> 目前搜索功能支持一下关键词搜索：<br> 标题，曲师，别名，落雪id,谱师</p><h2 id="筛选" tabindex="-1">筛选 <a class="header-anchor" href="#筛选" aria-label="Permalink to “筛选”">​</a></h2><p>软件对多种需求都尽量满足了，你可以按<strong>流派，版本，难度，bpm，游玩状态（需要落雪token设置好）分别筛选</strong><br> 你也可以<strong>多者结合起来筛选</strong>，比如：<br> 流派+版本<br> 流派+版本+难度<br> 流派流派+版本+难度+bpm<br> 流派流派+版本+难度+bpm+游玩状态<br> 流派流派+版本+难度+bpm+游玩状态+关键词<br><em>以及更多结合...</em></p><h2 id="特殊筛选" tabindex="-1">特殊筛选 <a class="header-anchor" href="#特殊筛选" aria-label="Permalink to “特殊筛选”">​</a></h2><p>有人说可以加一个音符筛选，那我就加一下吧）<br> 使用特殊筛选，请先选择 <em><strong>启用特殊筛选</strong></em></p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>该筛选方式需要配合最新最热歌曲数据使用，请确保你已经获取过最新最热歌曲数据</p></div><p><s>遥遥领先，优势在我</s></p><p>语法如下：</p><ul><li>$notetype 参数1</li><li>$notetype 参数1 参数2</li><li>$notetype 参数1 参数2|$notetype 参数1 参数2</li></ul><p>其中<strong>$total</strong>可以是total、tap、hold、slide、air、flick<br> 只输入参数1为筛选相等的音符数量<br> 输入参数1与参数2为 参数1~参数2的范围<br> 第三种语法是支持多种音符组合筛选</p><p>例如：<br><code>$total 2725 2727</code><img src="'+n+'" alt="pic1"></p><p>又例如：<br><code>$tap 1567 1569|$hold 187</code><img src="'+s+'" alt=""></p><h2 id="搜索结果展示" tabindex="-1">搜索结果展示 <a class="header-anchor" href="#搜索结果展示" aria-label="Permalink to “搜索结果展示”">​</a></h2><p><img src="'+l+'" alt="搜索结果展示"> 搜索结果会以这样的结果显示：<br><em><strong>曲绘 落雪id - 曲名 流派 - 版本 \\n 难度</strong></em><br> 点击结果即可进入歌曲详情页<br> 点击右下角浮动按钮可以回到顶部</p>',15)])])}const u=a(p,[["render",c]]);export{g as __pageData,u as default};
